import java.util.*; import java.io.*; public class Main { static class Element { int val, id; Element(int val, int id) { this.val = val; this.id = id; } } public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); StringTokenizer st = new StringTokenizer(br.readLine()); Element[] arr = new Element[n]; for (int i = 0; i < n; i++) { arr[i] = new Element(Integer.parseInt(st.nextToken()), i); } Arrays.sort(arr, Comparator.comparingInt(a -> a.val)); long[] results = new long[n]; long[] leftMid = new long[n]; long[] rightMid = new long[n]; for (int i = 0; i < n - 1; i++) { long mid = (long) Math.floor((arr[i].val + arr[i + 1].val) / 2.0); rightMid[i] = mid; leftMid[i + 1] = mid + 1; } for (int i = 0; i < n; i++) { long lower = (i == 0) ? Long.MIN_VALUE : leftMid[i]; long upper = (i == n - 1) ? Long.MAX_VALUE : rightMid[i]; if (lower == Long.MIN_VALUE || upper == Long.MAX_VALUE) { results[arr[i].id] = -1; } else { results[arr[i].id] = upper - lower + 1; } } for (int i = 0; i < n; i++) { out.print(results[i] + (i == n - 1 ? "" : " ")); } out.println(); } out.flush(); out.close(); } }